def is_good_triple(x, y, z):
    numerator = (x + 1)**y
    denominator = x**z + 1

    # Since x, y, z are positive integers, numerator and denominator are positive integers.
    # The condition is that the division results in a positive integer.
    if numerator % denominator == 0:
        return True
    return False

good_triples = []
for x in range(1, 6):
    for y in range(1, 6):
        for z in range(1, 6):
            if is_good_triple(x, y, z):
                good_triples.append((x, y, z))

print("Good Triples (x, y, z) for x, y, z in {1, 2, 3, 4, 5}:")
for triple in good_triples:
    print(triple)

print(f"\nTotal count: {len(good_triples)}")

